\midrule
\texttt{item\_id} & 57.8 & 62.5 & 60.1 & 60.1 & 2.37 & 0.039 \\
\texttt{prompt$\times$item} & --- & --- & --- & --- & --- & 0.061 \\
\texttt{seed$\times$item}  & --- & --- & --- & --- & --- & 0.073 \\
